// Original stadium crowd recording supplied by the app developer (MP3, unmodified).
// Embedded for deployment through text-only source control; served to the browser as audio/mpeg.
const sound = '';
export default function handler(req, res) {
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.status(405).setHeader('Allow', 'GET, HEAD').end(); return;
  }
  const buffer = Buffer.from(sound, 'base64');
  res.status(200).setHeader('Content-Type', 'audio/mpeg')
    .setHeader('Cache-Control', 'public, max-age=86400')
    .setHeader('X-Content-Type-Options', 'nosniff')
    .setHeader('Content-Length', buffer.length);
  if (req.method === 'HEAD') { res.end(); return; }
  res.end(buffer);
}